import {sessionCookieOptions} from './cookies.js';
import { randomUUID } from 'node:crypto';
import { AppError, signupInput, loginInput } from '@crew/shared';
import {issueCredential} from './credentials.js';
import { hashPassword, verifyPassword } from './passwords.js';
import { asyncRoute } from '../../http/errors.js';
import { hashToken, publicUser, requireAuth } from '../../http/middleware/auth.js';
export function registerAuth(ctx) {
  const {app,db,bus,config}=ctx;
  function session(req,res,user) {
    const token=issueCredential(config.secret,'session');
    const time=new Date().toISOString();
    const expires=new Date(Date.now()+config.sessionDays*86400000).toISOString();
    const id=randomUUID();
    db.prepare('INSERT INTO sessions(id,user_id,token_hash,created_at,expires_at,last_used_at,user_agent) VALUES (?,?,?,?,?,?,?)').run(id,user.id,hashToken(token),time,expires,time,req.headers['user-agent']??'');
    res.cookie('crew_session',token,{...sessionCookieOptions(config),maxAge:config.sessionDays*86400000});
    return id;
  }
  app.post('/api/v1/auth/signup',asyncRoute(async(req,res)=>{
    const input=signupInput(req.body);
    if(db.prepare('SELECT id FROM users WHERE email=?').get(input.email))throw new AppError('CONFLICT','Email already registered',409);
    const id=randomUUID();
    const time=new Date().toISOString();
    const hash=await hashPassword(input.password);
    db.prepare('INSERT INTO users VALUES (?,?,?,?,?,?)').run(id,input.email,input.name,hash,time,time);
    const user=publicUser(db.prepare('SELECT * FROM users WHERE id=?').get(id));
    session(req,res,user);
    bus.emit({actorId:id,entityType:'user',entityId:id,action:'created',after:user});
    res.status(201).json({user});
  }));
  app.post('/api/v1/auth/login',asyncRoute(async(req,res)=>{
    const input=loginInput(req.body);
    const row=db.prepare('SELECT * FROM users WHERE email=?').get(input.email);
    if(!row||!await verifyPassword(input.password,row.password_hash))throw new AppError('UNAUTHENTICATED','Email or password is incorrect',401);
    const user=publicUser(row);
    session(req,res,user);
    bus.emit({actorId:user.id,entityType:'user',entityId:user.id,action:'login',after:{email:user.email}});
    res.json({user});
  }));
  app.post('/api/v1/auth/logout',requireAuth,(req,res)=>{
    ctx.permissions.assertSelf(req,req.user.id,'self:write');
    if(req.auth.kind==='session')db.prepare('DELETE FROM sessions WHERE id=?').run(req.auth.sessionId);
    res.clearCookie('crew_session',sessionCookieOptions(config));
    bus.emit({actorId:req.user.id,entityType:'user',entityId:req.user.id,action:'logout'});
    res.json({ok:true});
  });
  app.get('/api/v1/me',requireAuth,(req,res)=>{ctx.permissions.assertSelf(req);res.json({user:req.user,auth:{kind:req.auth.kind,scopes:req.auth.scopes??null}});});
}

import {sessionCookieOptions} from '../auth/cookies.js';
import {AppError,fields,text,email} from '@crew/shared';
import {hashPassword,verifyPassword} from '../auth/passwords.js';
import {issueCredential,verifyCredential} from '../auth/credentials.js';
import {hashToken} from '../../http/middleware/auth.js';
import {securityEvent} from './security-events.js';
export const publicSession=(row,currentId)=>({id:row.id,createdAt:row.created_at,
  expiresAt:row.expires_at,lastUsedAt:row.last_used_at,userAgent:row.user_agent,current:row.id===currentId});
export function invalidateCredentials(ctx,userId,keepSessionId=null) {
  ctx.db.prepare('DELETE FROM sessions WHERE user_id=? AND id<>?').run(userId,keepSessionId??'');
  if(ctx.db.prepare("SELECT name FROM sqlite_master WHERE name='api_tokens'").get())ctx.db.prepare('UPDATE api_tokens SET revoked_at=? WHERE user_id=? AND revoked_at IS NULL').run(ctx.now(),userId);
}
export function registerAccount(ctx) {
  const {app,db,requireAuth,permissions:p}=ctx;
  app.get('/api/v1/auth/sessions',requireAuth,(req,res)=>{
    p.assertSelf(req);
    const rows=db.prepare('SELECT * FROM sessions WHERE user_id=? AND expires_at>? ORDER BY created_at DESC,id').all(req.user.id,ctx.now());
    res.json(ctx.paginate(rows.map(row=>publicSession(row,req.auth.sessionId)),req.query));
  });
  app.delete('/api/v1/auth/sessions/:sessionId',requireAuth,(req,res)=>{
    p.assertSelf(req,req.user.id,'self:write');
    const row=db.prepare('SELECT * FROM sessions WHERE id=? AND user_id=?').get(req.params.sessionId,req.user.id);
    if(!row)throw new AppError('NOT_FOUND','Session not found',404);
    db.prepare('DELETE FROM sessions WHERE id=?').run(row.id);
    if(row.id===req.auth.sessionId)res.clearCookie('crew_session',sessionCookieOptions(ctx.config));
    securityEvent(ctx,req,'session',row.id,'revoked',{before:publicSession(row,req.auth.sessionId)});
    res.json({ok:true,current:row.id===req.auth.sessionId});
  });
  app.post('/api/v1/auth/sessions/revoke-others',requireAuth,(req,res)=>{
    p.assertSelf(req,req.user.id,'self:write');fields(req.body,[]);
    const result=db.prepare('DELETE FROM sessions WHERE user_id=? AND id<>?').run(req.user.id,req.auth.sessionId??'');
    securityEvent(ctx,req,'user',req.user.id,'sessions_revoked',{after:{count:Number(result.changes)}});
    res.json({revoked:Number(result.changes)});
  });
  app.post('/api/v1/auth/password/change',requireAuth,ctx.asyncRoute(async(req,res)=>{
    p.assertSelf(req,req.user.id,'self:write');fields(req.body,['currentPassword','password']);
    const currentPassword=text(req.body.currentPassword,'currentPassword',{max:1024,trim:false});
    const password=text(req.body.password,'password',{min:10,max:1024,trim:false});
    const user=db.prepare('SELECT * FROM users WHERE id=?').get(req.user.id);
    if(!await verifyPassword(currentPassword,user.password_hash))throw new AppError('VALIDATION','Current password is incorrect',422,{currentPassword:'Current password is incorrect'});
    if(currentPassword===password)throw new AppError('VALIDATION','Choose a different password',422,{password:'Must differ from your current password'});
    const hash=await hashPassword(password);
    ctx.transaction(()=>{
      db.prepare('UPDATE users SET password_hash=?,updated_at=? WHERE id=?').run(hash,ctx.now(),req.user.id);
      invalidateCredentials(ctx,req.user.id,req.auth.sessionId);
      db.prepare('UPDATE password_resets SET revoked_at=? WHERE user_id=? AND used_at IS NULL AND revoked_at IS NULL').run(ctx.now(),req.user.id);
    });
    securityEvent(ctx,req,'user',req.user.id,'password_changed',{after:{otherSessionsRevoked:true,apiTokensRevoked:true}});
    res.json({ok:true,signInRequired:req.auth.kind!=='session'});
  }));
  app.post('/api/v1/auth/password/reset/request',(req,res)=>{
    fields(req.body,['email']);const address=email(req.body.email);
    const user=db.prepare('SELECT * FROM users WHERE email=?').get(address);
    if(user){
      const token=issueCredential(ctx.config.secret,'reset'),id=ctx.id(),time=ctx.now();
      const expiresAt=new Date(Date.now()+3600000).toISOString();
      ctx.transaction(()=>{
        db.prepare('UPDATE password_resets SET revoked_at=? WHERE user_id=? AND used_at IS NULL AND revoked_at IS NULL').run(time,user.id);
        db.prepare('INSERT INTO password_resets(id,user_id,token_hash,created_at,expires_at) VALUES (?,?,?,?,?)').run(id,user.id,hashToken(token),time,expiresAt);
        const link=ctx.config.baseUrl.replace(/\/$/,'')+'/#/reset?token='+encodeURIComponent(token);
        ctx.enqueueOutbox({userId:user.id,kind:'reset',toEmail:user.email,subject:'Reset your Crew password',textBody:'Reset your password: '+link,payload:{resetId:id,link,expiresAt}});
      });
      securityEvent(ctx,null,'user',user.id,'password_reset_requested',{actorId:user.id,after:{expiresAt}});
    }
    res.status(202).json({ok:true,message:'If the account exists, a reset link is in its outbox.'});
  });
  app.post('/api/v1/auth/password/reset',ctx.asyncRoute(async(req,res)=>{
    fields(req.body,['token','password']);
    const token=text(req.body.token,'token',{max:200});
    const password=text(req.body.password,'password',{min:10,max:1024,trim:false});
    if(!verifyCredential(ctx.config.secret,'reset',token))throw new AppError('VALIDATION','Reset link is invalid or expired',422,{token:'Request a new reset link'});
    const reset=db.prepare('SELECT * FROM password_resets WHERE token_hash=?').get(hashToken(token));
    if(!reset||reset.used_at||reset.revoked_at||reset.expires_at<=ctx.now())throw new AppError('VALIDATION','Reset link is invalid or expired',422,{token:'Request a new reset link'});
    const hash=await hashPassword(password);
    ctx.transaction(()=>{
      const current=db.prepare('SELECT * FROM password_resets WHERE id=?').get(reset.id);
      if(current.used_at||current.revoked_at||current.expires_at<=ctx.now())throw new AppError('CONFLICT','Reset link has already been used or expired',409);
      db.prepare('UPDATE users SET password_hash=?,updated_at=? WHERE id=?').run(hash,ctx.now(),reset.user_id);
      db.prepare('UPDATE password_resets SET used_at=? WHERE id=?').run(ctx.now(),reset.id);
      db.prepare('UPDATE password_resets SET revoked_at=? WHERE user_id=? AND id<>? AND used_at IS NULL AND revoked_at IS NULL').run(ctx.now(),reset.user_id,reset.id);
      invalidateCredentials(ctx,reset.user_id);
    });
    res.clearCookie('crew_session',sessionCookieOptions(ctx.config));
    securityEvent(ctx,null,'user',reset.user_id,'password_reset',{actorId:reset.user_id,after:{allSessionsRevoked:true,apiTokensRevoked:true}});
    res.json({ok:true,signInRequired:true});
  }));
}
